-- GENERATED by db/build-init.js from db/migrations/*.sql: do not edit by hand.
-- Applies each numbered migration once; safe to run on every deploy.
CREATE TABLE IF NOT EXISTS schema_migrations (
  version    TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  checksum   TEXT NOT NULL,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ===== migration 0001 baseline =====
SELECT COALESCE((SELECT checksum FROM schema_migrations WHERE version = '0001'), '') AS have \gset
SELECT (:'have' = '') AS fresh, (:'have' <> '' AND :'have' <> '90e76c56a0247eb0f84d8f1b14d903560bb5875248fe74ec8d03e31b1f7aebb3') AS drift \gset
\if :drift
  SELECT 'migration 0001 baseline was edited after it was applied; add a new migration instead'::int;
\endif
\if :fresh
BEGIN;
-- OpenHabit database schema (multi-user)
-- Ownership: users -> auth-service | habits -> habit-service
--            entries, wellness -> tracking-service | analytics: read-only

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ============================================================
-- users (owned by auth-service)
-- ============================================================
CREATE TABLE IF NOT EXISTS users (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email         TEXT NOT NULL UNIQUE,
  name          TEXT NOT NULL DEFAULT '',
  password_hash TEXT,                        -- NULL for SSO-only accounts
  oidc_sub      TEXT,                         -- OIDC subject (unique per issuer)
  oidc_iss      TEXT,                         -- OIDC issuer that vouches for oidc_sub
  ntfy_url      TEXT NOT NULL DEFAULT '',    -- ntfy topic URL for reminders
  timezone      TEXT NOT NULL DEFAULT 'UTC', -- IANA name, auto-set by the app
  quiet_start   TEXT NOT NULL DEFAULT '',    -- 'HH:MM' local; no reminders from here...
  quiet_end     TEXT NOT NULL DEFAULT '',    -- ...until here (may wrap midnight); '' = off
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ============================================================
-- habits (owned by habit-service)
-- ============================================================
CREATE TABLE IF NOT EXISTS habits (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  question    TEXT NOT NULL DEFAULT '',
  type        TEXT NOT NULL DEFAULT 'boolean' CHECK (type IN ('boolean', 'numeric')),
  unit        TEXT NOT NULL DEFAULT '',
  target      NUMERIC NOT NULL DEFAULT 1,
  target_type TEXT NOT NULL DEFAULT 'at_least' CHECK (target_type IN ('at_least', 'at_most')),
  color       TEXT NOT NULL DEFAULT '#7FD1AE',
  icon        TEXT NOT NULL DEFAULT '',
  schedule_type TEXT NOT NULL DEFAULT 'weekdays' CHECK (schedule_type IN ('weekdays', 'per_week')),
  frequency   INTEGER NOT NULL DEFAULT 3 CHECK (frequency BETWEEN 1 AND 7), -- times/week for per_week
  webhook_url TEXT NOT NULL DEFAULT '',
  reminder_time TEXT NOT NULL DEFAULT '',    -- 'HH:MM' local time, '' = off
  active_days INTEGER[] NOT NULL DEFAULT '{0,1,2,3,4,5,6}', -- 0=Sunday .. 6=Saturday
  position    INTEGER NOT NULL DEFAULT 0,
  archived    BOOLEAN NOT NULL DEFAULT FALSE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_habits_user ON habits (user_id, archived, position);

-- ============================================================
-- entries (owned by tracking-service); user scoping via habit FK
-- value = -1 is the SKIP sentinel: day excused, streak preserved
-- ============================================================
CREATE TABLE IF NOT EXISTS entries (
  habit_id  UUID NOT NULL REFERENCES habits (id) ON DELETE CASCADE,
  date      DATE NOT NULL,
  value     NUMERIC NOT NULL DEFAULT 1,
  notes     TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (habit_id, date)
);

CREATE INDEX IF NOT EXISTS idx_entries_date ON entries (date);

-- ============================================================
-- wellness (owned by tracking-service) - per user per day
-- ============================================================
CREATE TABLE IF NOT EXISTS wellness (
  user_id     UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  date        DATE NOT NULL,
  mood        INTEGER CHECK (mood BETWEEN 1 AND 5),
  sleep_hours NUMERIC CHECK (sleep_hours >= 0 AND sleep_hours <= 24),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, date)
);

-- ============================================================
-- Per-service roles (least privilege). Created without a password;
-- db/set-db-passwords.sh sets them from <SERVICE>_DB_PASSWORD.
-- ============================================================
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'auth_svc') THEN
    CREATE ROLE auth_svc LOGIN;  -- password set by db/set-db-passwords.sh
  END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'habit_svc') THEN
    CREATE ROLE habit_svc LOGIN;  -- password set by db/set-db-passwords.sh
  END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'tracking_svc') THEN
    CREATE ROLE tracking_svc LOGIN;  -- password set by db/set-db-passwords.sh
  END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'analytics_svc') THEN
    CREATE ROLE analytics_svc LOGIN;  -- password set by db/set-db-passwords.sh
  END IF;
END
$$;

GRANT SELECT, INSERT, UPDATE, DELETE ON users    TO auth_svc;
GRANT SELECT, INSERT, UPDATE, DELETE ON habits   TO habit_svc;
GRANT SELECT                          ON habits   TO tracking_svc, analytics_svc;
GRANT SELECT, INSERT, UPDATE, DELETE ON entries  TO tracking_svc;
GRANT SELECT, INSERT, UPDATE, DELETE ON wellness TO tracking_svc;
GRANT SELECT                          ON entries, wellness TO analytics_svc;

-- ============================================================
-- collaboration (owned by social-service)
-- ============================================================
CREATE TABLE IF NOT EXISTS groups (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name        TEXT NOT NULL,
  icon        TEXT NOT NULL DEFAULT '',
  owner_id    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  invite_code TEXT NOT NULL UNIQUE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS group_members (
  group_id  UUID NOT NULL REFERENCES groups (id) ON DELETE CASCADE,
  user_id   UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role      TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'member')),
  joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (group_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_group_members_user ON group_members (user_id);

CREATE TABLE IF NOT EXISTS group_invites (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id      UUID NOT NULL REFERENCES groups (id) ON DELETE CASCADE,
  inviter_id    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  invitee_email TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'declined')),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (group_id, invitee_email)
);

CREATE INDEX IF NOT EXISTS idx_group_invites_email ON group_invites (lower(invitee_email), status);

-- which habits a user exposes to a given group (opt-in, per habit)
CREATE TABLE IF NOT EXISTS habit_shares (
  habit_id  UUID NOT NULL REFERENCES habits (id) ON DELETE CASCADE,
  group_id  UUID NOT NULL REFERENCES groups (id) ON DELETE CASCADE,
  PRIMARY KEY (habit_id, group_id)
);

CREATE INDEX IF NOT EXISTS idx_habit_shares_group ON habit_shares (group_id);

-- habits owned by a group: everyone tracks the same thing
CREATE TABLE IF NOT EXISTS group_habits (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id   UUID NOT NULL REFERENCES groups (id) ON DELETE CASCADE,
  name       TEXT NOT NULL,
  question   TEXT NOT NULL DEFAULT '',
  icon       TEXT NOT NULL DEFAULT '',
  color      TEXT NOT NULL DEFAULT '#7FD1AE',
  created_by UUID REFERENCES users (id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_group_habits_group ON group_habits (group_id);

-- each member's check-in on a group habit (value 1 = done, -1 = skip/excused)
CREATE TABLE IF NOT EXISTS group_habit_entries (
  group_habit_id UUID NOT NULL REFERENCES group_habits (id) ON DELETE CASCADE,
  user_id        UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  date           DATE NOT NULL,
  value          NUMERIC NOT NULL DEFAULT 1,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (group_habit_id, user_id, date)
);

-- reactions on a member's shared habit (e.g. a flame on a streak)
CREATE TABLE IF NOT EXISTS reactions (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  group_id   UUID NOT NULL REFERENCES groups (id) ON DELETE CASCADE,
  from_user  UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  to_user    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  habit_id   UUID NOT NULL REFERENCES habits (id) ON DELETE CASCADE,
  emoji      TEXT NOT NULL DEFAULT '🔥',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (group_id, from_user, to_user, habit_id, emoji)
);

CREATE INDEX IF NOT EXISTS idx_reactions_to ON reactions (to_user, created_at);

-- social-service role
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'social_svc') THEN
    CREATE ROLE social_svc LOGIN;  -- password set by db/set-db-passwords.sh
  END IF;
END
$$;

GRANT SELECT, INSERT, UPDATE, DELETE ON groups, group_members, group_invites, habit_shares, reactions TO social_svc;
GRANT SELECT, INSERT, UPDATE, DELETE ON group_habits, group_habit_entries TO social_svc;
GRANT SELECT ON users  TO social_svc;   -- resolve invitee emails, member names
GRANT SELECT ON habits TO social_svc;   -- validate habit ownership on share
-- analytics reads shared data to build the group dashboard
GRANT SELECT ON groups, group_members, habit_shares, reactions TO analytics_svc;
GRANT SELECT ON group_habits, group_habit_entries TO analytics_svc;
GRANT SELECT ON users TO analytics_svc;

-- reminder-service: strictly read-only
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'reminder_svc') THEN
    CREATE ROLE reminder_svc LOGIN;  -- password set by db/set-db-passwords.sh
  END IF;
END
$$;
GRANT SELECT ON users, habits, entries TO reminder_svc;

-- ============================================================
-- Idempotent upgrades — safe to re-run on existing databases.
-- Fresh installs get these via CREATE TABLE above; older volumes
-- converge by running:  docker compose run --rm migrate
-- ============================================================
ALTER TABLE habits ADD COLUMN IF NOT EXISTS icon          TEXT    NOT NULL DEFAULT '';
ALTER TABLE habits ADD COLUMN IF NOT EXISTS schedule_type TEXT    NOT NULL DEFAULT 'weekdays';
ALTER TABLE habits ADD COLUMN IF NOT EXISTS frequency     INTEGER NOT NULL DEFAULT 3;
ALTER TABLE habits ADD COLUMN IF NOT EXISTS webhook_url   TEXT    NOT NULL DEFAULT '';
ALTER TABLE habits ADD COLUMN IF NOT EXISTS reminder_time  TEXT    NOT NULL DEFAULT '';
ALTER TABLE users  ADD COLUMN IF NOT EXISTS ntfy_url       TEXT    NOT NULL DEFAULT '';
ALTER TABLE users  ADD COLUMN IF NOT EXISTS timezone       TEXT    NOT NULL DEFAULT 'UTC';
ALTER TABLE users  ADD COLUMN IF NOT EXISTS oidc_sub       TEXT;
ALTER TABLE users  ADD COLUMN IF NOT EXISTS oidc_iss       TEXT;
ALTER TABLE users  ALTER COLUMN password_hash DROP NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_oidc ON users (oidc_iss, oidc_sub) WHERE oidc_sub IS NOT NULL;

-- ============================================================
-- Personal API tokens (long-lived, for automations/Shortcuts).
-- Only the SHA-256 hash is stored; the token is shown once.
-- ============================================================
CREATE TABLE IF NOT EXISTS api_tokens (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  token_hash   TEXT NOT NULL UNIQUE,
  prefix       TEXT NOT NULL,               -- first chars, for identification in the UI
  last_used_at TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_api_tokens_user ON api_tokens (user_id);

-- auth-service manages tokens; data-plane services verify them
GRANT SELECT, INSERT, UPDATE, DELETE ON api_tokens TO auth_svc;
GRANT SELECT, UPDATE ON api_tokens TO habit_svc, tracking_svc, analytics_svc, social_svc;
-- token auth resolves the user's email at request time
GRANT SELECT ON users TO habit_svc, tracking_svc;

-- ============================================================
-- Reminder bookkeeping (owned by reminder-service). One row per
-- habit per local day, claimed atomically before sending, so
-- restarts and extra replicas never double-send. snoozed_until is
-- set by the signed snooze link in the notification.
-- ============================================================
ALTER TABLE users ADD COLUMN IF NOT EXISTS quiet_start TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN IF NOT EXISTS quiet_end   TEXT NOT NULL DEFAULT '';

CREATE TABLE IF NOT EXISTS reminders_sent (
  habit_id      UUID NOT NULL REFERENCES habits (id) ON DELETE CASCADE,
  local_date    DATE NOT NULL,
  sent_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  snoozed_until TIMESTAMPTZ,
  PRIMARY KEY (habit_id, local_date)
);

GRANT SELECT, INSERT, UPDATE, DELETE ON reminders_sent TO reminder_svc;

-- ============================================================
-- Web Push subscriptions (one per browser/device). auth-service
-- manages them for the signed-in user; reminder-service reads them
-- to deliver and deletes ones the push service reports as gone.
-- ============================================================
CREATE TABLE IF NOT EXISTS push_subscriptions (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  endpoint   TEXT NOT NULL UNIQUE,
  p256dh     TEXT NOT NULL,
  auth       TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_push_subscriptions_user ON push_subscriptions (user_id);

GRANT SELECT, INSERT, UPDATE, DELETE ON push_subscriptions TO auth_svc;
GRANT SELECT, DELETE ON push_subscriptions TO reminder_svc;

-- ============================================================
-- Habit categories ("Health", "Work", …) and quit habits. A quit
-- habit is a yes/no, every-day habit where an entry records a
-- slip: days without one are the successes.
-- ============================================================
ALTER TABLE habits ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT '';
ALTER TABLE habits ADD COLUMN IF NOT EXISTS kind     TEXT NOT NULL DEFAULT 'build';
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_constraint WHERE conname = 'habits_kind_check') THEN
    ALTER TABLE habits ADD CONSTRAINT habits_kind_check CHECK (
      kind = 'build' OR (kind = 'quit' AND type = 'boolean' AND schedule_type = 'weekdays'));
  END IF;
END
$$;

-- ============================================================
-- Several reminders per habit (reminder_time holds up to 3 comma-separated
-- HH:MM times; reminders_sent keeps one row per time slot) and a "when/where"
-- cue shown with the habit and in its reminder.
-- ============================================================
ALTER TABLE habits ADD COLUMN IF NOT EXISTS cue TEXT NOT NULL DEFAULT '';
ALTER TABLE reminders_sent ADD COLUMN IF NOT EXISTS slot INTEGER NOT NULL DEFAULT 0;
DO $$
BEGIN
  IF (SELECT array_length(conkey, 1) FROM pg_constraint WHERE conname = 'reminders_sent_pkey') = 2 THEN
    ALTER TABLE reminders_sent DROP CONSTRAINT reminders_sent_pkey;
    ALTER TABLE reminders_sent ADD PRIMARY KEY (habit_id, local_date, slot);
  END IF;
END
$$;

-- ============================================================
-- Quit habits can value a clean day (e.g. 4 "$" or 20 "min"), so the habit
-- window can show what staying clean has saved.
-- ============================================================
ALTER TABLE habits ADD COLUMN IF NOT EXISTS savings_per_day NUMERIC NOT NULL DEFAULT 0;
ALTER TABLE habits ADD COLUMN IF NOT EXISTS savings_unit    TEXT    NOT NULL DEFAULT '';
INSERT INTO schema_migrations (version, name, checksum) VALUES ('0001', 'baseline', '90e76c56a0247eb0f84d8f1b14d903560bb5875248fe74ec8d03e31b1f7aebb3');
COMMIT;
\endif

-- ===== migration 0002 email_tokens =====
SELECT COALESCE((SELECT checksum FROM schema_migrations WHERE version = '0002'), '') AS have \gset
SELECT (:'have' = '') AS fresh, (:'have' <> '' AND :'have' <> '1263e2545124844ec55604edfc1056cd2afe5e9522da0d074cc58b144f444520') AS drift \gset
\if :drift
  SELECT 'migration 0002 email_tokens was edited after it was applied; add a new migration instead'::int;
\endif
\if :fresh
BEGIN;
-- Email verification and password reset (auth-service).
ALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified_at TIMESTAMPTZ;
-- accounts created through SSO were vouched for by the identity provider
UPDATE users SET email_verified_at = created_at WHERE oidc_sub IS NOT NULL AND email_verified_at IS NULL;

-- One-time links. Only a SHA-256 of the token is stored.
CREATE TABLE IF NOT EXISTS email_tokens (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('verify', 'reset')),
  email      TEXT NOT NULL,                 -- the address the link was sent to
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TIMESTAMPTZ NOT NULL,
  used_at    TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS email_tokens_user_idx ON email_tokens (user_id, kind);
GRANT SELECT, INSERT, UPDATE, DELETE ON email_tokens TO auth_svc;
INSERT INTO schema_migrations (version, name, checksum) VALUES ('0002', 'email_tokens', '1263e2545124844ec55604edfc1056cd2afe5e9522da0d074cc58b144f444520');
COMMIT;
\endif

-- ===== migration 0003 webhook_secret_version =====
SELECT COALESCE((SELECT checksum FROM schema_migrations WHERE version = '0003'), '') AS have \gset
SELECT (:'have' = '') AS fresh, (:'have' <> '' AND :'have' <> 'edeb5d0745dc23e3591425d1b13135478d83752c5849a17c5fde6d8a60ebe239') AS drift \gset
\if :drift
  SELECT 'migration 0003 webhook_secret_version was edited after it was applied; add a new migration instead'::int;
\endif
\if :fresh
BEGIN;
-- Signed webhooks: each user's signing secret is derived from JWT_SECRET, the user id and this version.
-- Bumping the version (auth-service: POST /auth/webhook-secret/rotate) replaces the secret.
ALTER TABLE users ADD COLUMN IF NOT EXISTS webhook_secret_version INTEGER NOT NULL DEFAULT 1;
INSERT INTO schema_migrations (version, name, checksum) VALUES ('0003', 'webhook_secret_version', 'edeb5d0745dc23e3591425d1b13135478d83752c5849a17c5fde6d8a60ebe239');
COMMIT;
\endif

-- ===== migration 0004 streak_freezes =====
SELECT COALESCE((SELECT checksum FROM schema_migrations WHERE version = '0004'), '') AS have \gset
SELECT (:'have' = '') AS fresh, (:'have' <> '' AND :'have' <> 'af99a30af4abaee5f25f17aa1bf7c28b46f196999e4072765e8a5ec66938cf2b') AS drift \gset
\if :drift
  SELECT 'migration 0004 streak_freezes was edited after it was applied; add a new migration instead'::int;
\endif
\if :fresh
BEGIN;
-- Streak protection: how many missed days per calendar month may be "frozen" (kept out of the streak)
-- for a daily habit. 0 turns it off. The freezes themselves are not stored: they are derived from the
-- entries, so editing a past day always gives a consistent answer.
ALTER TABLE habits ADD COLUMN IF NOT EXISTS streak_freezes SMALLINT NOT NULL DEFAULT 1
  CHECK (streak_freezes BETWEEN 0 AND 3);
INSERT INTO schema_migrations (version, name, checksum) VALUES ('0004', 'streak_freezes', 'af99a30af4abaee5f25f17aa1bf7c28b46f196999e4072765e8a5ec66938cf2b');
COMMIT;
\endif
